impl Default for KeysSettings {
    fn default() -> Self {
        Self {
            prefix: "ctrl+shift+space".into(),
            prefix_timeout_ms: 1000,
            bindings: BTreeMap::new(),
            prefix_bindings: crate::actions::default_prefix_bindings(),
            list_keys: true,
        }
    }
}

