/// Rust-model scrollback lines per session kind.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, TS, JsonSchema)]
#[serde(default, deny_unknown_fields)]
pub struct ScrollbackSettings {
    pub shell: u32,
    pub claude: u32,
    pub editor: u32,
    pub tool: u32,
    pub setup: u32,
    pub custom: u32,
}

impl Default for ScrollbackSettings {
    fn default() -> Self {
        Self { shell: 3000, claude: 3000, editor: 500, tool: 500, setup: 1000, custom: 3000 }
    }
}

impl ScrollbackSettings {
    /// Lines for a session kind name (`SessionKind::name()`).
    pub fn for_kind(&self, kind: &str) -> u32 {
        match kind {
            "shell" => self.shell,
            "claude" => self.claude,
            "editor" => self.editor,
            "tool" => self.tool,
            "setup" => self.setup,
            _ => self.custom,
        }
    }
}

/// Where terminal sessions live.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default, Serialize, Deserialize, TS, JsonSchema)]
#[serde(rename_all = "snake_case")]
pub enum SessionHost {
    /// PTYs in the app process: quitting ends them.
    Inprocess,
    /// PTYs in `keltad`: sessions survive quit and re-attach on the next start.
    #[default]
    Daemon,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, TS, JsonSchema)]
#[serde(default, deny_unknown_fields)]
pub struct TerminalSettings {
    /// System fonts only.
    pub font_family: String,
    #[schemars(range(min = 6.0, max = 40.0))]
    pub font_size: f64,
    #[schemars(range(min = 1.0, max = 2.0))]
    pub line_height: f64,
    pub letter_spacing: f64,
    /// auto = webgl on macOS, dom on Linux.
    pub renderer: Renderer,
    pub cursor_style: CursorStyle,
    /// Focused pane only.
    pub cursor_blink: bool,
    pub scrollback: ScrollbackSettings,
    #[schemars(range(min = 100, max = 10000))]
    pub view_scrollback: u32,
    #[schemars(range(min = 1, max = 12))]
    pub max_live_views: u32,
    #[schemars(range(min = 32, max = 2048))]
    pub memory_cap_mb: u32,
    /// Append scrolled-off lines (plain text) to an on-disk log per session: search + restore.
    pub history_log: bool,
    /// Per-session log cap (two rotated halves).
    #[schemars(range(min = 1, max = 1024))]
    pub history_log_mb: u32,
    /// Cap of all session logs; oldest files are deleted first.
    #[schemars(range(min = 16, max = 65536))]
    pub history_log_total_mb: u32,
    /// macOS.
    pub option_as_meta: OptionAsMeta,
    pub copy_on_select: bool,
    /// Linux: select → PRIMARY, middle-click paste.
    pub primary_selection: bool,
    /// Only when bracketed paste is off.
    pub confirm_multiline_paste: bool,
    pub osc52: Osc52,
    pub bell: BellMode,
    /// Session kind name (or `default`) → Shift+Enter handling.
    pub shift_enter: BTreeMap<String, ShiftEnter>,
    pub keyboard_protocol: KeyboardProtocol,
    /// Empty = `$SHELL`.
    pub shell: String,
    #[schemars(extend("x-kelta-exec" = true))]
    pub env: BTreeMap<String, String>,
    pub minimum_contrast_ratio: f64,
    /// `daemon` = sessions survive quit (keltad).
    #[schemars(extend("x-kelta-restart" = true, "x-kelta-scope" = ["global"]))]
    pub session_host: SessionHost,
}

impl Default for TerminalSettings {
    fn default() -> Self {
        Self {
            font_family: "JetBrains Mono, Menlo, DejaVu Sans Mono, monospace".into(),
            font_size: 13.0,
            line_height: 1.15,
            letter_spacing: 0.0,
            renderer: Renderer::Auto,
            cursor_style: CursorStyle::Block,
            cursor_blink: false,
            scrollback: ScrollbackSettings::default(),
            view_scrollback: 1000,
            max_live_views: 2,
            memory_cap_mb: 160,
            history_log: true,
            history_log_mb: 16,
            history_log_total_mb: 512,
            option_as_meta: OptionAsMeta::Both,
            copy_on_select: false,
            primary_selection: true,
            confirm_multiline_paste: true,
            osc52: Osc52::Write,
            bell: BellMode::Attention,
            shift_enter: BTreeMap::from([
                ("claude".to_owned(), ShiftEnter::EscCr),
                ("default".to_owned(), ShiftEnter::Passthrough),
            ]),
            keyboard_protocol: KeyboardProtocol::Legacy,
            shell: String::new(),
            env: BTreeMap::new(),
            minimum_contrast_ratio: 1.0,
            session_host: SessionHost::Daemon,
        }
    }
}

