pub struct EditorPreset {
    pub id: String,
    pub label: String,
    pub command: String,
    pub args: Vec<String>,
    pub open: EditorOpenMode,
    pub open_keys: Option<String>,
    pub open_cmd: Option<Vec<String>>,
    /// Launched outside Kelta (the template's editor pane becomes a shell).
    pub external: bool,
    pub restore: EditorRestore,
    pub enabled: bool,
}

impl Default for EditorPreset {
    fn default() -> Self {
        Self {
            id: String::new(),
            label: String::new(),
            command: String::new(),
            args: Vec::new(),
            open: EditorOpenMode::None,
            open_keys: None,
            open_cmd: None,
            external: false,
            restore: EditorRestore::None,
            enabled: true,
        }
    }
}

fn s(v: &str) -> String {
    v.to_owned()
}

fn sv(v: &[&str]) -> Vec<String> {
    v.iter().map(|x| (*x).to_owned()).collect()
}

/// SETTINGS §2.1.
pub fn default_editor_presets() -> Vec<EditorPreset> {
    vec![
        EditorPreset {
            id: s("nvim"),
            label: s("Neovim"),
            command: s("nvim"),
            args: sv(&["--listen", "{sock}", "{path}"]),
            open: EditorOpenMode::Rpc,
            restore: EditorRestore::Mksession,
            ..EditorPreset::default()
        },
        EditorPreset {
            id: s("vim"),
            label: s("Vim"),
            command: s("vim"),
            args: sv(&["{path}"]),
            open: EditorOpenMode::Keys,
            open_keys: Some(s("<C-\\><C-N>:edit +{line} {file}<CR>")),
            ..EditorPreset::default()
        },
        EditorPreset {
            id: s("helix"),
            label: s("Helix"),
            command: s("hx"),
            args: sv(&["{path}"]),
            open: EditorOpenMode::None,
            ..EditorPreset::default()
        },
        EditorPreset {
            id: s("emacs"),
            label: s("Emacs"),
            command: s("emacs"),
            args: sv(&[
                "-nw",
                "--eval",
                "(progn (setq server-name \"kelta-{sid8}\") (server-start))",
                "{path}",
            ]),
            open: EditorOpenMode::Command,
            open_cmd: Some(sv(&["emacsclient", "-s", "kelta-{sid8}", "-n", "+{line}", "{file}"])),
            ..EditorPreset::default()
        },
        EditorPreset {
            id: s("vscode"),
            label: s("VS Code"),
            external: true,
            command: s("code"),
            args: sv(&["{path}"]),
            open: EditorOpenMode::Command,
            open_cmd: Some(sv(&["code", "-g", "{file}:{line}"])),
            ..EditorPreset::default()
        },
        EditorPreset {
            id: s("zed"),
            label: s("Zed"),
            external: true,
            command: s("zed"),
            args: sv(&["{path}"]),
            open: EditorOpenMode::Command,
            open_cmd: Some(sv(&["zed", "{file}:{line}"])),
            ..EditorPreset::default()
        },
    ]
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, TS, JsonSchema)]
#[serde(default, deny_unknown_fields)]
pub struct EditorSettings {
    /// Preset id.
    pub default: String,
    pub follow_claude_edits: FollowEdits,
    /// The diff editor's arguments: appended for review sessions and used by Review diff on own work
    /// items, e.g. `["-c","DiffviewOpen {range}"]` (`{range}` = `<remote>/<base>` for own items, merge
    /// base to working tree; `<remote>/<base>...HEAD` for review checkouts). Empty: `git diff` in a shell.
    #[schemars(extend("x-kelta-scope" = ["global", "project", "repo"]))]
    pub review_args: Vec<String>,
    #[schemars(extend("x-kelta-merge" = "by_id", "x-kelta-exec" = true))]
    pub presets: Vec<EditorPreset>,
}

impl Default for EditorSettings {
    fn default() -> Self {
        Self {
            default: "nvim".into(),
            follow_claude_edits: FollowEdits::Reload,
            review_args: Vec::new(),
            presets: default_editor_presets(),
        }
    }
}

