/// `{ split = "row", ratios = [..], children = [..] }` | `{ session = "claude", ... }`.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, TS, JsonSchema)]
#[serde(untagged)]
pub enum TemplateNode {
    Split {
        split: SplitDir,
        ratios: Vec<f32>,
        children: Vec<TemplateNode>,
    },
    Session {
        /// `claude` | `editor` | `shell` | `setup` | `tool:<id>`.
        session: String,
        #[serde(default)]
        name: Option<String>,
        /// Claude profile.
        #[serde(default)]
        profile: Option<String>,
        /// Shell: run this then stay interactive.
        #[serde(default)]
        command: Option<String>,
    },
}

impl Default for TemplateNode {
    fn default() -> Self {
        Self::session("shell")
    }
}

impl TemplateNode {
    pub fn session(kind: &str) -> Self {
        Self::Session { session: kind.to_owned(), name: None, profile: None, command: None }
    }
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, TS, JsonSchema)]
#[serde(default, deny_unknown_fields)]
pub struct SessionTemplate {
    pub id: String,
    pub label: String,
    pub layout: TemplateNode,
    pub enabled: bool,
}

impl Default for SessionTemplate {
    fn default() -> Self {
        Self { id: String::new(), label: String::new(), layout: TemplateNode::default(), enabled: true }
    }
}

/// SETTINGS §2 defaults.
pub fn default_session_templates() -> Vec<SessionTemplate> {
    let t = |id: &str, label: &str, layout: TemplateNode| SessionTemplate {
        id: id.to_owned(),
        label: label.to_owned(),
        layout,
        enabled: true,
    };
    vec![
        t(
            "claude+editor",
            "Claude + editor",
            TemplateNode::Split {
                split: SplitDir::Row,
                ratios: vec![0.5, 0.5],
                children: vec![TemplateNode::session("claude"), TemplateNode::session("editor")],
            },
        ),
        t(
            "review",
            "Review",
            TemplateNode::Split {
                split: SplitDir::Row,
                ratios: vec![0.5, 0.5],
                children: vec![
                    TemplateNode::Session {
                        session: s("claude"),
                        name: None,
                        profile: Some(s("review")),
                        command: None,
                    },
                    TemplateNode::Split {
                        split: SplitDir::Column,
                        ratios: vec![0.75, 0.25],
                        children: vec![
                            TemplateNode::session("editor"),
                            TemplateNode::Session {
                                session: s("shell"),
                                name: None,
                                profile: None,
                                command: Some(s("git diff --stat origin/{base}...HEAD")),
                            },
                        ],
                    },
                ],
            },
        ),
        t("claude", "Claude", TemplateNode::session("claude")),
        t("editor", "Editor", TemplateNode::session("editor")),
        t("shell", "Shell", TemplateNode::session("shell")),
    ]
}

